/* opengl32.dll for the guest: the gl* entry points (opengl32_gen.c, generated by
 * tools/gen_gl.py) and the hand-written ones and wgl* (opengl32.c). */
#ifndef COD_OPENGL32_H
#define COD_OPENGL32_H

#include "shim.h"

#if defined(__vita__)
#include <vitaGL.h>
#elif defined(__SWITCH__)
#include "gl_switch.h"
#elif defined(__APPLE__)
#include <OpenGL/gl.h>
#include <OpenGL/glext.h>
#else
#include <GL/gl.h>
#include <GL/glext.h>
#endif

typedef struct GlEntry {
    const char *name;
    GuestFn fn;        /* guest-callable entry */
    void **host;       /* where the host function is stored (NULL: hand-written) */
} GlEntry;

extern const GlEntry g_gl_entries[];
extern const unsigned g_gl_entry_count;

/* Host address of a GL function (core or extension), NULL if the driver has none. */
void *platform_gl_proc(const char *name);

/* GLfloat / GLdouble stack arguments (slot = 4-byte stack slot index). */
static inline GLfloat argf(Ctx *c, int slot)
{
    uint32_t v = ARG(slot);
    float f;
    memcpy(&f, &v, 4);
    return f;
}

static inline GLdouble argd(Ctx *c, int slot)
{
    uint64_t v = (uint64_t)ARG(slot) | ((uint64_t)ARG(slot + 1) << 32);
    double d;
    memcpy(&d, &v, 8);
    return d;
}

/* Frame trace (Cmd+P, or "trace" in COD_INPUT): every GL call of one frame is
 * logged with its first stack arguments. */
extern int g_gl_tracing;
void gl_trace_call(Ctx *c, const char *name);
#define GL_TRACE(name) do { if (__builtin_expect(g_gl_tracing, 0)) gl_trace_call(c, (name)); } while (0)

/* Address the guest gets from GetProcAddress(opengl32) / wglGetProcAddress. */
uint32_t opengl32_get_proc(const char *name);

#endif
